// apps/api/test/tradeflowkit-recurring-jobs.test.ts
process.env.SESSION_SECRET ||= "operatoros-tradeflowkit-recurring-jobs-test-v1";
var app;
var ownerA;
var ownerB;
var viewer;
var moduleRow;
var insertedModule = false;
var signToken2;
function headers(user7, tenantId4) {
  return {
    authorization: `Bearer ${signToken2({
      userId: user7.id,
      email: user7.email,
      role: user7.role,
      tokenVersion: user7.tokenVersion,
      sessionType: "platform"
    })}`,
    "x-tenant-id": tenantId4
  };
}
before(async () => {
  await ensureSchemaReady();
  ({ signToken: signToken2 } = await Promise.resolve().then(() => (init_auth2(), auth_exports)));
  ownerA = await createTestUser();
  ownerB = await createTestUser();
  viewer = await createTestUser();
  [moduleRow] = await db.select().from(modules).where(eq26(modules.slug, "tradeflowkit")).limit(1);
  if (!moduleRow) {
    moduleRow = await createTestModule("tradeflowkit");
    insertedModule = true;
  }
  await db.insert(tenantUsers).values({ tenantId: ownerA.currentTenantId, userId: viewer.id, role: "viewer" });
  await db.insert(tenantModules).values([
    { tenantId: ownerA.currentTenantId, moduleId: moduleRow.id, status: "enabled", source: "admin", allowAllMembers: true },
    { tenantId: ownerB.currentTenantId, moduleId: moduleRow.id, status: "enabled", source: "admin", allowAllMembers: true }
  ]).onConflictDoNothing();
  await db.insert(tenantUserModuleAccess).values({
    tenantId: ownerA.currentTenantId,
    userId: viewer.id,
    moduleId: moduleRow.id,
    accessLevel: "viewer"
  }).onConflictDoNothing();
  const Fastify = (await import("fastify")).default;
  const cookie = (await import("@fastify/cookie")).default;
  app = Fastify();
  await app.register(cookie);
  const { registerModuleShellRoutes: registerModuleShellRoutes2 } = await Promise.resolve().then(() => (init_module_shell_routes(), module_shell_routes_exports));
  await registerModuleShellRoutes2(app);
  await app.ready();
});
after(async () => {
  if (app) await app.close();
  for (const tenantId4 of [ownerA?.currentTenantId, ownerB?.currentTenantId].filter(Boolean)) {
    await db.execute(sql47`DELETE FROM shared_activity_events WHERE tenant_id = ${tenantId4}`);
    await db.execute(sql47`DELETE FROM shared_jobs WHERE tenant_id = ${tenantId4}`);
    await db.execute(sql47`DELETE FROM shared_schedules WHERE tenant_id = ${tenantId4}`);
  }
  if (moduleRow) {
    await db.delete(tenantUserModuleAccess).where(eq26(tenantUserModuleAccess.moduleId, moduleRow.id));
    await db.delete(tenantModules).where(eq26(tenantModules.moduleId, moduleRow.id));
  }
  for (const user7 of [viewer, ownerA, ownerB]) if (user7) await cleanupUser(user7.id);
  if (insertedModule && moduleRow) await cleanupModule(moduleRow.id);
});
test("P24-RECURRING-001: recurring jobs persist, deny viewers and foreign tenants, and replay idempotently", async () => {
  const tenantId4 = ownerA.currentTenantId;
  const customerResponse = await app.inject({
    method: "POST",
    url: "/v1/modules/tradeflowkit/customers",
    headers: headers(ownerA, tenantId4),
    payload: { name: "Recurring Route Customer", email: "recurring-route@example.test" }
  });
  assert.equal(customerResponse.statusCode, 201, customerResponse.body);
  const customer = customerResponse.json();
  const viewerDenied = await app.inject({
    method: "POST",
    url: "/v1/modules/tradeflowkit/recurring-jobs",
    headers: headers(viewer, tenantId4),
    payload: { name: "Denied", customerId: customer.id, title: "Denied job", intervalDays: 7, nextRunAt: (/* @__PURE__ */ new Date()).toISOString() }
  });
  assert.equal(viewerDenied.statusCode, 403, viewerDenied.body);
  const scheduledFor = new Date(Date.now() - 6e4).toISOString();
  const created = await app.inject({
    method: "POST",
    url: "/v1/modules/tradeflowkit/recurring-jobs",
    headers: headers(ownerA, tenantId4),
    payload: {
      name: "Weekly service route",
      customerId: customer.id,
      title: "Preventive service visit",
      description: "Created by the shared scheduler.",
      priority: "high",
      intervalDays: 7,
      durationMinutes: 90,
      nextRunAt: scheduledFor
    }
  });
  assert.equal(created.statusCode, 201, created.body);
  const schedule = created.json().schedule;
  assert.equal(schedule.enabled, true);
  const ownerList = await app.inject({ method: "GET", url: "/v1/modules/tradeflowkit/recurring-jobs", headers: headers(ownerA, tenantId4) });
  assert.equal(ownerList.statusCode, 200, ownerList.body);
  assert.equal(ownerList.json().schedules.length, 1);
  const foreignList = await app.inject({ method: "GET", url: "/v1/modules/tradeflowkit/recurring-jobs", headers: headers(ownerB, ownerB.currentTenantId) });
  assert.equal(foreignList.statusCode, 200, foreignList.body);
  assert.deepEqual(foreignList.json().schedules, []);
  assert.equal(await enqueueDueSchedules({ limit: 10 }), 1);
  assert.equal(await processSharedJobBatch({ workerId: "phase24-recurring-worker", limit: 10 }), 1);
  const jobs = await db.execute(sql47`
    SELECT id, tenant_id, source_id, status, scheduled_start, scheduled_end
    FROM tradeflowkit_jobs
    WHERE tenant_id = ${tenantId4} AND source_id LIKE ${`shared-schedule:${schedule.id}:%`}
  `);
  assert.equal(jobs.rows.length, 1);
  assert.equal(jobs.rows[0].status, "scheduled");
  assert.equal(new Date(jobs.rows[0].scheduled_end).getTime() - new Date(jobs.rows[0].scheduled_start).getTime(), 90 * 6e4);
  await db.execute(sql47`UPDATE shared_schedules SET next_run_at = ${new Date(scheduledFor)} WHERE tenant_id = ${tenantId4} AND id = ${schedule.id}`);
  assert.equal(await enqueueDueSchedules({ limit: 10 }), 1);
  assert.equal(await processSharedJobBatch({ workerId: "phase24-recurring-replay-worker", limit: 10 }), 0);
  const replayed = await db.execute(sql47`
    SELECT COUNT(*)::int AS count FROM tradeflowkit_jobs
    WHERE tenant_id = ${tenantId4} AND source_id LIKE ${`shared-schedule:${schedule.id}:%`}
  `);
  assert.equal(replayed.rows[0].count, 1);
  const disabled = await app.inject({
    method: "PATCH",
    url: `/v1/modules/tradeflowkit/recurring-jobs/${schedule.id}`,
    headers: headers(ownerA, tenantId4),
    payload: { expectedVersion: schedule.version, enabled: false }
  });
  assert.equal(disabled.statusCode, 200, disabled.body);
  assert.equal(disabled.json().schedule.enabled, false);
  const staleMutation = await app.inject({
    method: "PATCH",
    url: `/v1/modules/tradeflowkit/recurring-jobs/${schedule.id}`,
    headers: headers(ownerA, tenantId4),
    payload: { expectedVersion: schedule.version, enabled: true }
  });
  assert.equal(staleMutation.statusCode, 409, staleMutation.body);
  const foreignMutation = await app.inject({
    method: "PATCH",
    url: `/v1/modules/tradeflowkit/recurring-jobs/${schedule.id}`,
    headers: headers(ownerB, ownerB.currentTenantId),
    payload: { expectedVersion: disabled.json().schedule.version, enabled: true }
  });
  assert.equal(foreignMutation.statusCode, 409, foreignMutation.body);
});
